  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* --------------------------------------------------------------------
   * Local restrict-qualified aliases.
   *
   * PolyBench passes all arrays as pointers; the compiler must assume
   * that they may alias, which can inhibit vectorization and scalar
   * replacement.  We know from the benchmark setup that A, s, q, p, r
   * are all distinct, so we create local 'restrict' aliases to make
   * that information explicit to the optimizer.
   * ------------------------------------------------------------------ */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE *restrict s_ = s;
  DATA_TYPE *restrict q_ = q;
  DATA_TYPE *restrict p_ = p;
  DATA_TYPE *restrict r_ = r;

  /* Tunable tile size for the i-dimension (rows of A).
     Tiling i does not change the execution order of the (i,j) pairs
     within each tile, but it can improve cache/TLB behavior for very
     large problems and provides a natural outer loop that can be
     parallelized if desired. */
  const int T_I = 64;

#pragma scop
  /* Initialize s exactly as in the original kernel, but using the
     scalar macro to keep the code generic w.r.t. DATA_TYPE. */
  for (i = 0; i < _PB_M; i++)
    s_[i] = SCALAR_VAL(0.0);

  /* BiCG kernel:
     - q[i] = sum_j A[i][j] * p[j]
     - s[j] = sum_i r[i] * A[i][j]
     The two products are fused so that each A[i][j] load feeds both. */
  for (int ii = 0; ii < _PB_N; ii += T_I)
  {
    int i_max = ii + T_I;
    if (i_max > _PB_N)
      i_max = _PB_N;

    for (i = ii; i < i_max; ++i)
    {
      /* Keep row-scalar r[i] and the accumulator for q[i] in registers. */
      DATA_TYPE ri = r_[i];
      DATA_TYPE qi = SCALAR_VAL(0.0);

      /* Pointer to the current row of A for cheap, unit-stride access. */
      DATA_TYPE *restrict A_row = A_[i];

      /* Manually unroll the inner j-loop by 4.
         This increases instruction-level parallelism and exposes a
         simple, unit-stride access pattern to the compiler, which
         typically enables efficient SIMD vectorization. */
      int j_end    = _PB_M;
      int j_unroll = j_end & ~3; /* largest multiple of 4 <= _PB_M */

      for (j = 0; j < j_unroll; j += 4)
      {
        DATA_TYPE a0 = A_row[j    ];
        DATA_TYPE a1 = A_row[j + 1];
        DATA_TYPE a2 = A_row[j + 2];
        DATA_TYPE a3 = A_row[j + 3];

        /* s = A^T * r: update four entries of s in a row. */
        s_[j    ] += ri * a0;
        s_[j + 1] += ri * a1;
        s_[j + 2] += ri * a2;
        s_[j + 3] += ri * a3;

        /* q = A * p: accumulate into the scalar qi. */
        qi += a0 * p_[j    ];
        qi += a1 * p_[j + 1];
        qi += a2 * p_[j + 2];
        qi += a3 * p_[j + 3];
      }

      /* Handle the remaining columns if M is not a multiple of 4. */
      for (; j < j_end; ++j)
      {
        DATA_TYPE a = A_row[j];
        s_[j] += ri * a;
        qi    += a * p_[j];
      }

      /* Store the completed dot-product for this row. */
      q_[i] = qi;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_bicg (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(s),
	       POLYBENCH_ARRAY(q),
	       POLYBENCH_ARRAY(p),
	       POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}
