/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Original semantics:
 *   s[j] = sum_i r[i] * A[i][j]       (s = A^T * r)
 *   q[i] = sum_j A[i][j] * p[j]       (q = A * p)
 *
 * Optimizations applied:
 *   - Explicit tiling in the row (i) and column (j) dimensions to
 *     improve cache locality for A, p, and s.
 *   - Register blocking for q[i] via a small per-tile buffer q_tile[]
 *     so each q[i] is written to memory only once.
 *   - Hoisting of r[i] into a scalar inside the inner loops.
 *   - Inner-most loop over j kept unit-stride for A, p and s to
 *     enable efficient auto-vectorization.
 */
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j, I, J;

  /* Tile sizes chosen empirically for typical PolyBench sizes and
     x86-64 cache hierarchies. They can be tuned further if needed. */
  enum { T_I = 32,      /* rows per tile  */
         T_J = 256 };   /* columns per tile */

  /* Temporary buffer that holds partial q[i] values for one tile of rows.
     This lets us keep q in registers/L1 and write back once per row. */
  DATA_TYPE q_tile[T_I];

#pragma scop
  /* Initialize s exactly once, as in the original kernel. */
  for (i = 0; i < _PB_M; i++)
    s[i] = SCALAR_VAL(0.0);

  /* Tiled BiCG kernel:
   *   Outer loop tiles the rows (I).
   *   For each row tile:
   *     - q_tile[] holds partial dot-products for rows in that tile.
   *     - We iterate over column tiles (J) and update:
   *         s[j]  += r[i] * A[i][j]
   *         q_tile[i-I] += A[i][j] * p[j]
   *     - At the end, q_tile is written back to q[].
   */
  for (I = 0; I < _PB_N; I += T_I)
  {
    int i_end       = I + T_I;
    if (i_end > _PB_N)
      i_end = _PB_N;
    int tile_height = i_end - I;

    /* Initialize the partial q for this tile of rows. */
    for (i = 0; i < tile_height; ++i)
      q_tile[i] = SCALAR_VAL(0.0);

    /* Loop over column tiles. */
    for (J = 0; J < _PB_M; J += T_J)
    {
      int j_end      = J + T_J;
      if (j_end > _PB_M)
        j_end = _PB_M;
      int tile_width = j_end - J;

      /* For each row in the current tile, update s[j] and q_tile. */
      for (i = 0; i < tile_height; ++i)
      {
        int row       = I + i;
        DATA_TYPE ri  = r[row];
        DATA_TYPE qi  = q_tile[i];

        /* Pointers into the current row of A and the current column tile of
           p and s. All are contiguous in j, which is crucial for SIMD. */
        DATA_TYPE *restrict a_row   = &A[row][J];
        DATA_TYPE *restrict p_block = &p[J];
        DATA_TYPE *restrict s_block = &s[J];

        /* Inner-most j-loop: unit-stride accesses to A, p and s.
           Marked with ivdep to encourage aggressive vectorization. */
#pragma GCC ivdep
        for (j = 0; j < tile_width; ++j)
        {
          DATA_TYPE a_ij = a_row[j];
          s_block[j] += ri * a_ij;
          qi        += a_ij * p_block[j];
        }

        q_tile[i] = qi;
      }
    }

    /* Commit the accumulated q values for this tile back to memory. */
    for (i = 0; i < tile_height; ++i)
    {
      int row = I + i;
      q[row]  = q_tile[i];
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
