/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* Tunable tile sizes. Chosen to give good cache locality on typical
     PolyBench sizes without assuming divisibility of N or M. */
  const int tile_i = 64;
  const int tile_j = 256;

#pragma scop
  /* Separate, vectorizable initialization of outputs. */
  for (j = 0; j < _PB_M; j++)
    s[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    q[i] = SCALAR_VAL(0.0);

  /* Tiled traversal of A to improve cache locality.
     - i-tiles keep a small strip of rows in cache.
     - j-tiles keep segments of A, p, and s in L1/L2.
     The ordering of updates to each s[j] and q[i] is preserved, so the
     floating-point results are bit-identical to the original code. */
  for (int ii = 0; ii < _PB_N; ii += tile_i)
  {
    int i_end = ii + tile_i;
    if (i_end > _PB_N)
      i_end = _PB_N;

    for (int jj = 0; jj < _PB_M; jj += tile_j)
    {
      int j_end = jj + tile_j;
      if (j_end > _PB_M)
        j_end = _PB_M;

      const int len = j_end - jj;

      for (i = ii; i < i_end; ++i)
      {
        /* Keep per-row values in registers. */
        DATA_TYPE ri = r[i];
        DATA_TYPE qi = q[i]; /* partial sum across j-tiles */

        /* Use contiguous pointers for the current tile to help
           the compiler generate efficient, unit-stride vector code. */
        DATA_TYPE *restrict A_row = &A[i][jj];
        DATA_TYPE *restrict p_tile = &p[jj];
        DATA_TYPE *restrict s_tile = &s[jj];

        /* Inner j-loop over a contiguous tile.
           - A_row[j], p_tile[j], s_tile[j] are all unit-stride.
           - 'ivdep' asserts absence of cross-iteration dependencies. */
#pragma GCC ivdep
        for (j = 0; j < len; ++j)
        {
          DATA_TYPE A_ij = A_row[j];
          s_tile[j] += ri * A_ij;
          qi       += A_ij * p_tile[j];
        }

        q[i] = qi;
      }
    }
  }
#pragma endscop
}


