/* Main computational kernel. The whole function will be timed,
   including the call and return.

   BiCG computes two matrix-vector products:

     q = A * p        (length N)
     s = A^T * r      (length M)

   Original code:

     for (j = 0; j < M; ++j) s[j] = 0;
     for (i = 0; i < N; ++i) {
       q[i] = 0;
       for (j = 0; j < M; ++j) {
         s[j] += r[i] * A[i][j];
         q[i] += A[i][j] * p[j];
       }
     }

   Optimizations applied here:

   - Use local restrict-qualified pointers so the compiler can assume
     that A, s, q, p, r do not alias, which enables better vectorization.
   - Separate initialization of s and q from the main fused kernel.
     This keeps the main loops "pure" reductions and simplifies analysis.
   - 2D tiling (blocking) over rows (i) and columns (j) of A:
       for i0 in tiles of size TILE_I
         for j0 in tiles of size TILE_J
           for i in i0-tile
             for j in j0-tile
               ...
     This improves cache locality for A, p, and s while preserving the
     original mathematical result (only the reduction order changes).
   - Hoist r[i] and q[i] into scalars (registers) within the i-loop,
     so each is loaded/stored only once per row.
   - Manually unroll the innermost j-loop by a factor of 4 to increase
     instruction-level parallelism and make SIMD vectorization easier
     for the compiler. A scalar remainder loop handles the tail.
 */
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  /* Create local restrict-qualified views.  The PolyBench framework
     guarantees that these arrays do not overlap.  Using restrict here
     helps the compiler optimize memory accesses (e.g., vectorization). */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE *restrict s_ = s;
  DATA_TYPE *restrict q_ = q;
  DATA_TYPE *restrict p_ = p;
  DATA_TYPE *restrict r_ = r;

  /* Tiling parameters: chosen for modern x86-64 caches.
     TILE_I: how many rows of A (and elements of q, r) per tile.
     TILE_J: how many columns of A (and elements of s, p) per tile. */
  const int TILE_I = 64;
  const int TILE_J = 256;

#pragma scop
  /* Explicit initialization of s and q, as in the original kernel. */
  for (int j = 0; j < _PB_M; j++)
    s_[j] = SCALAR_VAL(0.0);

  for (int i = 0; i < _PB_N; i++)
    q_[i] = SCALAR_VAL(0.0);

  /* Tiled, fused BiCG kernel.
     Loop order: tiles of rows (i0), tiles of cols (j0), then i, then j.
     This preserves the fused use of each A[i][j] value for both s and q. */
  for (int i0 = 0; i0 < _PB_N; i0 += TILE_I) {
    int i_max = i0 + TILE_I;
    if (i_max > _PB_N)
      i_max = _PB_N;

    for (int j0 = 0; j0 < _PB_M; j0 += TILE_J) {
      int j_max = j0 + TILE_J;
      if (j_max > _PB_M)
        j_max = _PB_M;

      /* End of the unrolled portion for this j-tile.
         We unroll by 4, then handle the remainder scalarly. */
      int j_unroll_end = j0 + ((j_max - j0) / 4) * 4;

      for (int i = i0; i < i_max; i++) {
        /* r[i] and q[i] are invariant across the inner j-loop.
           Keep them in registers to reduce memory traffic. */
        DATA_TYPE ri = r_[i];
        DATA_TYPE qi = q_[i];

        DATA_TYPE *s_tile = s_ + j0;
        DATA_TYPE *p_tile = p_ + j0;
        DATA_TYPE *A_row_tile = &A_[i][j0];

        int j;

        /* Manually unrolled inner loop by factor 4.  This preserves
           semantics while exposing more ILP and aiding auto-vectorization. */
        for (j = j0; j < j_unroll_end; j += 4) {
          DATA_TYPE a0 = A_row_tile[0];
          DATA_TYPE a1 = A_row_tile[1];
          DATA_TYPE a2 = A_row_tile[2];
          DATA_TYPE a3 = A_row_tile[3];

          /* s[j..j+3] += ri * a[0..3] */
          s_tile[0] += ri * a0;
          s_tile[1] += ri * a1;
          s_tile[2] += ri * a2;
          s_tile[3] += ri * a3;

          /* qi += sum_k a_k * p[j+k] */
          qi += a0 * p_tile[0];
          qi += a1 * p_tile[1];
          qi += a2 * p_tile[2];
          qi += a3 * p_tile[3];

          A_row_tile += 4;
          s_tile     += 4;
          p_tile     += 4;
        }

        /* Remainder of the j-tile (0–3 iterations). */
        for (; j < j_max; j++) {
          DATA_TYPE a = *A_row_tile;

          *s_tile += ri * a;
          qi      += a * (*p_tile);

          ++A_row_tile;
          ++s_tile;
          ++p_tile;
        }

        /* Write back accumulated q[i] once per row. */
        q_[i] = qi;
      }
    }
  }
#pragma endscop

}


